//! Synthetic-scale guard for #138: directory durability work grows linearly
//! with the file count and never fails.
//!
//! Generated bytes only, no real media. Kept in its own test binary because
//! `dir_sync_counts` is process-wide. `ALBUMEN_DIR_SYNC_SCALE_FILES` may raise
//! the count for a local run; the default keeps `cargo test` quick.

use std::fs;
use std::path::PathBuf;

use albumen_ingest::dest::dir_sync_counts;
use albumen_ingest::{copy_verify_file, sha256_hex};

fn file_count() -> usize {
    std::env::var("ALBUMEN_DIR_SYNC_SCALE_FILES")
        .ok()
        .and_then(|v| v.parse().ok())
        .filter(|n| *n >= 2)
        .unwrap_or(400)
}

#[test]
fn directory_sync_is_linear_and_never_fails_at_scale() {
    let n = file_count();
    let tmp = tempfile::tempdir().unwrap();
    let src = tmp.path().join("src");
    let dst = tmp.path().join("library");
    fs::create_dir_all(&src).unwrap();

    let mut sources: Vec<PathBuf> = Vec::with_capacity(n);
    for i in 0..n {
        let path = src.join(format!("IMG_{i:05}.JPG"));
        // Distinct bytes per file so no two copies look alike.
        let mut bytes = format!("synthetic #{i} ").into_bytes();
        bytes.resize(512 + (i % 97), (i % 251) as u8);
        fs::write(&path, &bytes).unwrap();
        sources.push(path);
    }
    let source_hashes: Vec<String> = sources.iter().map(|p| sha256_hex(p).unwrap()).collect();

    // One warm-up file measures the per-file cost on this platform.
    let (f0, w0, x0) = dir_sync_counts();
    copy_verify_file(&sources[0], &dst).unwrap();
    let (f1, w1, x1) = dir_sync_counts();
    let per_file = (f1 - f0) + (w1 - w0);
    assert_eq!(x1 - x0, 0, "a directory sync failed on the first file");
    assert!(per_file >= 1, "the first file was not made durable");

    for source in &sources[1..] {
        copy_verify_file(source, &dst).unwrap();
    }
    let (f2, w2, x2) = dir_sync_counts();

    assert_eq!(x2 - x0, 0, "a directory sync failed at scale");
    // The destination directory already exists after the first file, so later
    // files may need less directory work, never more.
    let rest = (f2 - f1) + (w2 - w1);
    assert!(
        rest <= per_file * (n as u64 - 1),
        "directory sync work grew faster than the file count: {rest} for {} files, {per_file} per file",
        n - 1
    );
    assert!(
        rest >= n as u64 - 1,
        "a file was stored without a directory sync"
    );

    // Bit-exact copies and untouched sources.
    for (source, hash) in sources.iter().zip(&source_hashes) {
        assert_eq!(&sha256_hex(source).unwrap(), hash, "source changed");
        let stored = dst.join(source.file_name().unwrap());
        assert_eq!(&sha256_hex(&stored).unwrap(), hash, "copy not bit-exact");
    }
}
